`timescale 1ns / 1ps

// WB-stage write-back monitor for lab1 RV32core.
// Logs every register write at the WB stage and checks X/Z propagation.
module wb_check_tb;
    reg clk, rst;
    integer cycle = 0;
    integer errors = 0;
    integer writes = 0;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0),
        .pc(), .inst(), .mem_addr(), .mem_data()
    );

    initial begin
        clk = 0;
        rst = 1;
        #3 rst = 0;
    end
    always #5 clk = ~clk;

    // monitor WB stage on the falling edge (values stable after posedge update)
    always @(negedge clk) begin
        if (!rst) begin
            cycle = cycle + 1;
            if (core.RegWrite_WB === 1'bx || core.RegWrite_WB === 1'bz) begin
                $display("ERROR: RegWrite_WB is X/Z at cycle %0d", cycle);
                errors = errors + 1;
            end else if (core.RegWrite_WB) begin
                writes = writes + 1;
                if (^core.rd_WB === 1'bx || ^core.wt_data_WB === 1'bx) begin
                    $display("ERROR: X in WB write at cycle %0d: PC=%h rd=%0d data=%h",
                             cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
                    errors = errors + 1;
                end else begin
                    $display("WB cycle=%0d PC=%h rd=x%0d data=%h",
                             cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
                end
            end
            if (cycle > 300) begin
                $display("DONE: %0d writes, %0d errors", writes, errors);
                $finish;
            end
        end
    end
endmodule

`timescale 1ns / 1ps

// Self-checking WB-stage monitor for lab1 RV32core running core/rom.mem
// (source: lab1/all_test.s). Expected write-back values hand-derived from
// the assembly + core/ram.mem initial data.
// Pass criterion: every non-x0 register write appears in order with the
// expected PC/rd/data; no X/Z on WB signals; program loops back to PC 0
// after the jalr at 0x128.
module wb_selfcheck_tb;
    reg clk, rst;
    integer cycle = 0;
    integer errors = 0;
    integer idx = 0;        // index into expected table
    integer loops = 0;

    // expected: {PC, rd, data} for each non-x0 write, in program order
    reg [68:0] expected [0:41];
    initial begin
        expected[ 0] = {32'h00000004, 5'd2, 32'h00000008}; // lw x2,4(x0)
        expected[ 1] = {32'h00000008, 5'd4, 32'h00000010}; // lw x4,8(x0)
        expected[ 2] = {32'h0000000c, 5'd1, 32'h00000018}; // add
        expected[ 3] = {32'h00000010, 5'd1, 32'h00000017}; // addi -1
        expected[ 4] = {32'h00000014, 5'd5, 32'h00000014}; // lw x5,12(x0)
        expected[ 5] = {32'h00000018, 5'd6, 32'hffff0000}; // lw x6,16(x0)
        expected[ 6] = {32'h0000001c, 5'd7, 32'h0fff0000}; // lw x7,20(x0)
        expected[ 7] = {32'h00000020, 5'd1, 32'h00000008}; // sub
        expected[ 8] = {32'h00000024, 5'd1, 32'h00000000}; // and
        expected[ 9] = {32'h00000028, 5'd1, 32'h00000018}; // or
        expected[10] = {32'h0000002c, 5'd1, 32'h00000018}; // xor
        expected[11] = {32'h00000030, 5'd1, 32'h00001000}; // sll
        expected[12] = {32'h00000034, 5'd1, 32'h00000000}; // slt
        expected[13] = {32'h00000038, 5'd1, 32'h00000001}; // slt
        expected[14] = {32'h0000003c, 5'd1, 32'h00ffff00}; // srl
        expected[15] = {32'h00000040, 5'd1, 32'hffffff00}; // sra
        expected[16] = {32'h00000044, 5'd1, 32'h000fff00}; // sra
        expected[17] = {32'h00000048, 5'd1, 32'h00000000}; // sltu
        expected[18] = {32'h0000004c, 5'd1, 32'h00000001}; // sltu
        expected[19] = {32'h00000054, 5'd1, 32'hfffffffd}; // addi x1,x10,-3
        expected[20] = {32'h00000058, 5'd1, 32'h00000000}; // andi
        expected[21] = {32'h0000005c, 5'd1, 32'h0000001f}; // ori
        expected[22] = {32'h00000060, 5'd1, 32'h0000001f}; // xori
        expected[23] = {32'h00000064, 5'd1, 32'h00000000}; // slti
        expected[24] = {32'h00000068, 5'd1, 32'h00000020}; // slli
        expected[25] = {32'h0000006c, 5'd1, 32'h00000004}; // srli
        expected[26] = {32'h00000070, 5'd1, 32'hfffffff0}; // srai
        expected[27] = {32'h00000074, 5'd1, 32'h00000001}; // sltiu
        expected[28] = {32'h00000078, 5'd1, 32'h00000001}; // sltiu
        expected[29] = {32'h000000e8, 5'd1, 32'h00004000}; // lui
        expected[30] = {32'h000000ec, 5'd1, 32'h000000f0}; // jal x1,12
        expected[31] = {32'h000000f8, 5'd8, 32'hff000f0f}; // lw x8,24(x0)
        expected[32] = {32'h00000100, 5'd1, 32'hff000f0f}; // lw after sw
        expected[33] = {32'h00000108, 5'd1, 32'h00000f0f}; // lw after sh
        expected[34] = {32'h00000110, 5'd1, 32'h0000000f}; // lw after sb
        expected[35] = {32'h00000114, 5'd1, 32'hffffff00}; // lh
        expected[36] = {32'h00000118, 5'd1, 32'h0000ff00}; // lhu
        expected[37] = {32'h0000011c, 5'd1, 32'hffffffff}; // lb
        expected[38] = {32'h00000120, 5'd1, 32'h000000ff}; // lbu
        expected[39] = {32'h00000124, 5'd1, 32'hffff0124}; // auipc
        expected[40] = {32'h00000128, 5'd1, 32'h0000012c}; // jalr x1,0(x0)
        expected[41] = {32'h00000004, 5'd2, 32'h00000008}; // loop: lw x2 again
    end

    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'd0), .debug_data(),
        .clk(clk), .rst(rst), .interrupter(1'b0),
        .pc(), .inst(), .mem_addr(), .mem_data()
    );

    initial begin
        clk = 0;
        rst = 1;
        #12 rst = 0;
    end
    always #5 clk = ~clk;

    reg [31:0] exp_pc, exp_data;
    reg [4:0]  exp_rd;
    always @(negedge clk) begin
        if (!rst) begin
            cycle = cycle + 1;
            if (core.RegWrite_WB !== 1'b0 && core.RegWrite_WB !== 1'b1) begin
                $display("FAIL: RegWrite_WB X/Z at cycle %0d", cycle);
                errors = errors + 1;
            end else if (core.RegWrite_WB) begin
                if ((^core.rd_WB === 1'bx) || (^core.wt_data_WB === 1'bx) || (^core.PC_WB === 1'bx)) begin
                    $display("FAIL: X/Z in WB at cycle %0d PC=%h rd=%0d data=%h",
                             cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
                    errors = errors + 1;
                end else if (core.rd_WB != 5'd0) begin
                    if (idx > 41) begin
                        $display("FAIL: unexpected extra write cycle=%0d PC=%h rd=x%0d data=%h",
                                 cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
                        errors = errors + 1;
                    end else begin
                        {exp_pc, exp_rd, exp_data} = expected[idx];
                        if (core.PC_WB !== exp_pc || core.rd_WB !== exp_rd || core.wt_data_WB !== exp_data) begin
                            $display("FAIL: write #%0d cycle=%0d got PC=%h rd=x%0d data=%h, expected PC=%h rd=x%0d data=%h",
                                     idx, cycle, core.PC_WB, core.rd_WB, core.wt_data_WB,
                                     exp_pc, exp_rd, exp_data);
                            errors = errors + 1;
                        end else begin
                            $display("ok: #%0d cycle=%0d PC=%h rd=x%0d data=%h",
                                     idx, cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
                        end
                        idx = idx + 1;
                        if (idx == 42) loops = loops + 1;
                    end
                end
